        requires
            log_size == LOG_SIZE,
            0 < num_replicas && num_replicas <= MAX_REPLICAS,
        ensures
            res.0.wf(),
            res.0.unbounded_log_instance@ == res.2@.unbounded_log_instance,
            res.0.cyclic_buffer_instance@ == res.2@.cyclic_buffer_instance,
            res.1.len() == num_replicas,
